/* LINER-UPDATE id="chg-pw-br-v1" title="علامت قرمز تغییرات + رمز ویرایش/حذف + شاخه‌ی چندتایی" base="v6" */
(function () {
  if (window.__LINER_CPB) return;
  window.__LINER_CPB = 1;

  /* ================= 0) ابزارهای کمکی ================= */
  // SHA-256 همزمان (فقط ASCII)؛ رمز به‌صورت هش ذخیره می‌شود، نه متن ساده
  function sha256(ascii) {
    function rr(v, a) { return (v >>> a) | (v << (32 - a)); }
    var mp = Math.pow, mw = mp(2, 32), i, j, result = '', words = [];
    var bl = ascii.length * 8;
    var hash = [], k = [], pc = 0, comp = {};
    for (var cand = 2; pc < 64; cand++) {
      if (!comp[cand]) {
        for (i = 0; i < 313; i += cand) comp[i] = cand;
        hash[pc] = (mp(cand, .5) * mw) | 0;
        k[pc++] = (mp(cand, 1 / 3) * mw) | 0;
      }
    }
    ascii += '\x80';
    while (ascii.length % 64 - 56) ascii += '\x00';
    for (i = 0; i < ascii.length; i++) {
      j = ascii.charCodeAt(i);
      if (j >> 8) return '';
      words[i >> 2] |= j << ((3 - i) % 4) * 8;
    }
    words[words.length] = ((bl / mw) | 0);
    words[words.length] = bl;
    for (j = 0; j < words.length;) {
      var w = words.slice(j, j += 16), old = hash;
      hash = hash.slice(0, 8);
      for (i = 0; i < 64; i++) {
        var w15 = w[i - 15], w2 = w[i - 2], a = hash[0], e = hash[4];
        var t1 = hash[7] + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) + ((e & hash[5]) ^ ((~e) & hash[6])) + k[i] +
          (w[i] = (i < 16) ? w[i] : (w[i - 16] + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10))) | 0);
        var t2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
        hash = [(t1 + t2) | 0].concat(hash);
        hash[4] = (hash[4] + t1) | 0;
      }
      for (i = 0; i < 8; i++) hash[i] = (hash[i] + old[i]) | 0;
    }
    for (i = 0; i < 8; i++) for (j = 3; j + 1; j--) {
      var b = (hash[i] >> (j * 8)) & 255;
      result += ((b < 16) ? 0 : '') + b.toString(16);
    }
    return result;
  }

  // هش کوتاه برای امضای هر شاخه
  function h53(s) {
    var h1 = 0xdeadbeef, h2 = 0x41c6ce57, i, ch;
    for (i = 0; i < s.length; i++) {
      ch = s.charCodeAt(i);
      h1 = Math.imul(h1 ^ ch, 2654435761);
      h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
  }

  /* ================= 1) رمز عبور (root2500) ================= */
  // هش رمز داخل همین فایل اپدیت است و با اپدیت‌ها روی گیت‌هاب ذخیره/همگام می‌شود
  var PW_HASH = 'b9b73d6143452d7b5e9c097f98be808ac7984156f27b4178b23b7021d7711705';
  function pwOk(p) { return sha256('liner|' + String(p || '')) === PW_HASH; }

  LU.css(
    '#pwm{position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,.65);display:flex;align-items:center;justify-content:center;padding:16px}' +
    '#pwm[hidden]{display:none}' +
    '#pwm .tyb input{width:100%;box-sizing:border-box;direction:ltr;text-align:center;font-size:18px}' +
    '#pwm .pwe{color:#d11;font-weight:700;min-height:1.4em;font-size:13px}' +
    '.chg{color:#e11d1d!important;font-weight:800;font-size:.82em;margin-inline-start:6px;unicode-bidi:isolate;direction:ltr;display:inline-block}' +
    '.chgc{font-size:.8em}'
  );
  LU.html('body', 'beforeend',
    '<div id="pwm" hidden><div class="tyb" role="dialog" aria-modal="true">' +
    '<h3 id="pwt">رمز لازم است</h3>' +
    '<input id="pwi" type="password" autocomplete="off" placeholder="رمز">' +
    '<div class="pwe" id="pwe"></div>' +
    '<div style="display:flex;gap:8px"><button class="p" id="pwok" style="flex:1">تأیید</button><button id="pwno" style="flex:1">انصراف</button></div>' +
    '</div></div>');

  var PWCB = null;
  function pwClose() { $('pwm').hidden = true; PWCB = null; $('pwi').value = ''; $('pwe').textContent = ''; }
  function pwAsk(title, cb) {
    PWCB = cb;
    $('pwt').textContent = title || 'رمز لازم است';
    $('pwi').value = ''; $('pwe').textContent = '';
    $('pwm').hidden = false;
    setTimeout(function () { try { $('pwi').focus(); } catch (e) { } }, 60);
  }
  function pwSubmit() {
    var v = $('pwi').value;
    if (!pwOk(v)) { $('pwe').textContent = 'رمز اشتباه است.'; $('pwi').value = ''; $('pwi').focus(); return; }
    var cb = PWCB; pwClose();
    if (cb) cb();
  }
  $('pwok').onclick = pwSubmit;
  $('pwno').onclick = pwClose;
  $('pwi').onkeydown = function (e) { if (e.key === 'Enter') { e.preventDefault(); pwSubmit(); } else if (e.key === 'Escape') pwClose(); };
  window.liner_pwAsk = pwAsk;

  // --- ویرایش لاین (شامل حذف حرکت داخل ویرایشگر) ---
  var _openEdit = window.openEdit;
  window.openEdit = function (l) {
    if (l && byId(l.id)) { pwAsk('رمز ویرایش لاین «' + l.name + '»', function () { _openEdit(l); }); return; }
    return _openEdit(l);
  };

  // --- یادداشت‌گذاری روی حرکت در حالت مرور (تغییر مستقیم لاین) ---
  var _openNt = window.openNt;
  window.openNt = function (nd, x) {
    if (x === 'V') { pwAsk('رمز ویرایش یادداشت', function () { _openNt(nd, x); }); return; }
    return _openNt(nd, x);
  };

  // --- حذف لاین (و همه‌ی شاخه‌های داخلش) و حذف دیتابیس ---
  var _listClick = $('list').onclick;
  $('list').onclick = function (e) {
    var t = e.target, a = t.dataset && t.dataset.a, v = t.dataset && t.dataset.v;
    if (a === 'del' && CF === v) {
      var ln = byId(v);
      pwAsk('رمز حذف لاین «' + (ln ? ln.name : '') + '» و همه‌ی شاخه‌هایش', function () {
        CF = v; _listClick.call($('list'), { target: t });
      });
      return;
    }
    return _listClick.call(this, e);
  };
  var _dbDel = window.dbDel;
  window.dbDel = function (id) {
    if (DBL.cf !== id) return _dbDel(id);
    pwAsk('رمز حذف دیتابیس', function () { DBL.cf = id; _dbDel(id); });
  };

  // --- حذف / نصب / خاموش کردن اپدیت‌ها (تا کسی رمز را با حذف اپدیت دور نزند) ---
  var _updl = $('updl').onclick;
  $('updl').onclick = function (e) {
    var t = e.target;
    if (t.dataset && t.dataset.uid) { pwAsk('رمز حذف اپدیت', function () { _updl.call($('updl'), { target: t }); }); return; }
    return _updl.call(this, e);
  };
  var _updInstall = window.updInstall;
  window.updInstall = function (code) { pwAsk('رمز نصب/جایگزینی اپدیت', function () { _updInstall(code); }); };
  var _updon = $('updon').onchange;
  $('updon').onchange = function () {
    var el = this, want = el.checked; el.checked = !want;
    pwAsk('رمز تغییر اجرای اپدیت‌ها', function () { el.checked = want; _updon.call(el); });
  };

  // --- وارد کردن دستی پشتیبان (می‌تواند لاین‌ها را جایگزین/حذف کند)؛ همگام‌سازی خودکار گیت‌هاب آزاد است ---
  var _im = $('im').onclick;
  $('im').onclick = function () {
    if (window.ghApply) return _im.apply(this, arguments);
    var self = this, args = arguments;
    pwAsk('رمز وارد کردن پشتیبان', function () { _im.apply(self, args); });
  };

  /* ================= 2) علامت قرمز شاخه‌های جدید/تغییرکرده ================= */
  function sigs(l) {
    return brPaths(l.tree).map(function (p) { return h53(p.map(function (n) { return n.san; }).join(' ')); });
  }
  // خط‌های موجود هنگام نصب = مبنا (قرمز نمی‌شوند)
  S.lines.forEach(function (l) { if (!l.sg && l.tree) { try { l.sg = sigs(l); } catch (e) { } } });
  save();

  var _mark = window.mark;
  window.mark = function (id) {
    try {
      var l = byId(id);
      if (l && l.tree && !PUB) {
        var cur = sigs(l);
        if (!l.sg) {
          if (!l.ts) l.chg = cur.slice();          // لاین کاملاً جدید: همه‌ی شاخه‌ها
          l.sg = cur;
        } else {
          var old = {}; l.sg.forEach(function (h) { old[h] = 1; });
          var add = cur.filter(function (h) { return !old[h]; });
          if (add.length) l.chg = add;               // تغییر جدید جایگزین قبلی می‌شود
          l.sg = cur;
        }
      }
    } catch (e) { }
    return _mark.apply(this, arguments);
  };

  var CNC = {};
  function chgNums(l) {
    if (!l || !l.chg || !l.chg.length || !l.tree) return [];
    var key = l.id + '|' + (l.ts || 0) + '|' + (l.ut || 0) + '|' + l.chg.length;
    if (CNC[l.id] && CNC[l.id].k === key) return CNC[l.id].v;
    var set = {}; l.chg.forEach(function (h) { set[h] = 1; });
    var r = []; sigs(l).forEach(function (h, i) { if (set[h]) r.push(i + 1); });
    CNC[l.id] = { k: key, v: r };
    return r;
  }
  window.chgB = function (l) {
    var n = chgNums(l);
    return n.length ? ' <span class="chg" title="شاخه‌های جدید/تغییرکرده">' + brTxt(n) + '</span>' : '';
  };
  window.catChg = function (arr, c, full) {
    if (c === DBN) return '';
    var u = {}, a = [];
    (arr || []).forEach(function (l) { chgNums(l).forEach(function (n) { u[n] = 1; }); });
    Object.keys(u).forEach(function (n) { a.push(+n); });
    if (!a.length) return '';
    a.sort(function (x, y) { return x - y; });
    var t = brTxt(a);
    if (!full && t.length > 18) t = t.slice(0, 18) + '…';
    return ' <span class="chg chgc">' + t + '</span>';
  };
  LU.patch('rowHtml', 'esc(l.name)+accB(l)', 'esc(l.name)+accB(l)+chgB(l)');
  LU.patch('renderLib', "' ('+cats[c].length+')'+(c!==DBN", "' ('+cats[c].length+')'+catChg(cats[c],c)+(c!==DBN");
  LU.patch('renderLib', "esc(c)+' ('+cats[c].length+')</h2>'", "esc(c)+' ('+cats[c].length+')'+catChg(cats[c],c,1)+'</h2>'");

  /* ================= 3) شماره شاخه: بازه (1-10) و انتخابی (1*4*7) ================= */
  window.brParse = function (s, max) {
    s = String(s == null ? '' : s).trim();
    if (!s || s === '0') return null;                       // خالی/۰ = همه
    s = s.replace(/[\u06F0-\u06F9]/g, function (d) { return d.charCodeAt(0) - 0x06F0; })
      .replace(/[\u0660-\u0669]/g, function (d) { return d.charCodeAt(0) - 0x0660; })
      .replace(/[\u2013\u2014\u2212~]/g, '-')
      .replace(/[\u00D7xX\u2715\u2217\uFF0A]/g, '*')
      .replace(/[\u060C,;\u061B\/\\|]+/g, '*')
      .replace(/\s*-\s*/g, '-').replace(/\s+/g, '*');
    var out = new Set();
    s.split('*').filter(Boolean).forEach(function (t) {
      var m = /^(\d+)-(\d+)$/.exec(t), a, b, i;
      if (m) {
        a = +m[1]; b = +m[2]; if (a > b) { i = a; a = b; b = i; }
        for (i = Math.max(a, 1); i <= Math.min(b, max); i++) out.add(i);
      } else if (/^\d+$/.test(t)) {
        a = +t; if (a >= 1 && a <= max) out.add(a);
      } else throw new Error('قالب نامعتبر است. مثال: 1-10 یا 1*4*7');
    });
    return out;
  };
  function selTxt(sel) {
    var a = []; sel.forEach(function (n) { a.push(n); }); a.sort(function (x, y) { return x - y; });
    return brTxt(a);
  }

  ['ebrn', 'rbrn'].forEach(function (id) {
    var e = $(id); if (!e) return;
    e.type = 'text'; e.setAttribute('inputmode', 'text'); e.setAttribute('dir', 'ltr');
    e.placeholder = '۰ = همه | 1-10 | 1*4*7';
  });

  window.brApply = function (k) {
    var x = k === 'e' ? E : V; if (!x) return;
    var raw = $(k === 'e' ? 'ebrn' : 'rbrn').value;
    if (k === 'e') exitAn(); else { if (AR) { toast('اول مرور خودکار رو متوقف کن.'); return; } if (V.free) $('rfree').onclick(); }
    var ps = brPaths(brTree(x)), sel;
    try { sel = brParse(raw, ps.length); } catch (err) { toast(err.message); return; }
    if (sel && !sel.size) { toast('شاخه‌ای با این شماره نیست. این لاین ' + ps.length + ' شاخه دارد.'); return; }
    var allow = null;
    if (sel) { allow = new Set(); ps.forEach(function (p, i) { if (sel.has(i + 1)) p.forEach(function (n) { allow.add(n); }); }); }
    x.br = sel ? (sel.size === 1 ? sel.values().next().value : selTxt(sel)) : 0;
    x.allow = allow;
    JP = true;
    if (k === 'e') { while (E.path.length) eBack(); } else { while (V.path.length) rvBack(); }
    JP = false; x.fwd = []; B = x; render();
    if (k === 'e') upEd(); else upRv();
    toast(sel ? 'فقط شاخه‌ی ' + x.br + ' نمایش داده می‌شه.' : 'همه‌ی شاخه‌ها نمایش داده می‌شه.');
  };
  // مرور خودکار هم از بازه/چندتایی پشتیبانی کند
  LU.patch('arRun', 'if(i===0&&me.br&&ps[me.br-1])ps=[ps[me.br-1]];',
    "if(i===0&&me.br&&typeof me.br==='string'){var _bs=brParse(me.br,ps.length);if(_bs)ps=ps.filter(function(p,q){return _bs.has(q+1)})}else if(i===0&&me.br&&ps[me.br-1])ps=[ps[me.br-1]];");

  /* ================= 4) انتخاب شاخه‌ها در بخش تمرین ================= */
  var PBS = '', PXC = {};
  function prune(n, allow) {
    return { san: n.san, lb: n.lb, ty: n.ty, nt: n.nt, _o: n, c: n.c.filter(function (c) { return allow.has(c); }).map(function (c) { return prune(c, allow); }) };
  }
  function pxGet(b, spec) {
    var ps = brPaths(b.tree), sel = brParse(spec, ps.length);
    if (sel === null) return b;
    if (!sel.size) return null;
    var key = b.id + '|' + spec, sig = ps.length + ':' + cnt(b.tree) + ':' + (b.ut || 0) + ':' + (b.ts || 0);
    if (PXC[key] && PXC[key].sig === sig) return PXC[key].px;
    var allow = new Set();
    ps.forEach(function (p, i) { if (sel.has(i + 1)) p.forEach(function (n) { allow.add(n); }); });
    var pr = { c: b.tree.c.filter(function (c) { return allow.has(c); }).map(function (c) { return prune(c, allow); }), _orig: b.tree };
    var px = new Proxy(b, { get: function (t, k) { if (k === 'tree') return pr; if (k === '__orig') return t; return t[k]; } });
    PXC[key] = { sig: sig, px: px };
    return px;
  }
  // شماره‌ی شاخه‌ها در تمرین نسبت به لاین اصلی بماند
  var _brNums = window.brNums;
  window.brNums = function (tree, node) {
    if (tree && tree._orig) return _brNums(tree._orig, (node && node !== tree) ? node._o : null);
    return _brNums(tree, node);
  };
  var _start = window.start;
  window.start = function (set, same) {
    var base = function (l) { return l && l.__orig ? l.__orig : l; };
    var out = [], sp, spec = PBS;
    try {
      set.forEach(function (l) {
        var b = base(l); if (!b || !b.tree || !b.tree.c.length) return;
        var px = pxGet(b, spec); if (px) out.push(px);
      });
      if (same) sp = pxGet(base(same), spec);
    } catch (err) { toast(err.message); return; }
    if (!out.length) { toast('در این لاین/دسته شاخه‌ای با این شماره‌ها نیست.'); return; }
    var r = _start(out, sp || undefined);
    var i2 = $('pbrsi2'); if (i2) i2.textContent = spec ? 'تمرین فقط روی شاخه‌های ' + spec + ' (شماره‌ها نسبت به هر لاین)' : '';
    return r;
  };

  var BR_UI =
    '<input id="PID" type="text" dir="ltr" inputmode="text" autocomplete="off" placeholder="خالی = همه | 1-10 | 1*4*7" style="flex:1;min-width:0">';
  LU.html('#list', 'beforebegin',
    '<div class="bar" style="margin:8px 0 4px;align-items:center"><span class="meta" style="flex:0 0 auto">شاخه‌های تمرین</span>' +
    BR_UI.replace('PID', 'pbrs') + '</div>' +
    '<div class="meta" style="margin:0 0 8px">بازه: <b dir="ltr">1-10</b> — انتخابی: <b dir="ltr">1*4*7</b>. روی تمرین یک لاین یا کل دسته اعمال می‌شه.</div>');
  LU.html('#pbr', 'afterend',
    '<div class="bar" style="margin:6px 0;align-items:center"><span class="meta" style="flex:0 0 auto">شاخه‌ها</span>' +
    BR_UI.replace('PID', 'pbrs2') + '<button id="pbrg">اعمال</button></div><div class="meta" id="pbrsi2"></div>');

  function syncPbs(v, from) {
    PBS = v.trim();
    ['pbrs', 'pbrs2'].forEach(function (id) { if (id !== from && $(id)) $(id).value = v; });
  }
  $('pbrs').oninput = function () { syncPbs(this.value, 'pbrs'); };
  $('pbrs2').oninput = function () { syncPbs(this.value, 'pbrs2'); };
  $('pbrg').onclick = function () {
    syncPbs($('pbrs2').value, 'pbrs2');
    if (!P) return;
    var set = P.set, same = P.line;
    start(set, same);
  };
  $('pbrs2').onkeydown = function (e) { if (e.key === 'Enter') { e.preventDefault(); $('pbrg').onclick(); } };

  try { renderLib(); } catch (e) { }
})();
